def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    start = n - 10
    if start < 0:
        start = 0

    opp_d = 0
    own_d = 0
    suck = 0
    unprov = 0
    forg = 0
    recent_opp_d = 0
    recent_suck = 0

    for i, (a, b) in enumerate(history):
        if a == 'D':
            own_d += 1
        if b == 'D':
            opp_d += 1
        if a == 'C' and b == 'D':
            suck += 1

        if i >= start:
            if b == 'D':
                recent_opp_d += 1
            if a == 'C' and b == 'D':
                recent_suck += 1

        if i == 0:
            if b == 'D':
                unprov += 1
        else:
            if b == 'D' and history[i - 1][0] == 'C':
                unprov += 1
            if b == 'C' and history[i - 1][0] == 'D':
                forg += 1

    recent_opp_c = (n - start) - recent_opp_d

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    own_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            own_streak += 1
        else:
            break

    hostile = False
    if n >= 12 and recent_opp_d >= 10 and recent_opp_c == 0:
        hostile = True
    elif n >= 16 and recent_opp_d >= 9 and recent_opp_c <= 1:
        hostile = True
    elif unprov >= 8 and opp_d >= own_d + 2 and recent_opp_d >= 7:
        hostile = True
    elif suck >= 7 and recent_opp_d >= 8:
        hostile = True

    if n >= 98:
        return 'D'

    if opp_last == 'D':
        if hostile:
            return 'D'

        if own_streak >= 4:
            if unprov <= 4 and (recent_opp_c >= 2 or recent_suck <= 2 or n <= 12):
                return 'C'
            if recent_opp_c >= 1 and unprov <= 6 and n < 70:
                return 'C'

        if my_last == 'C' and n >= 2 and history[-2][0] == 'D':
            if unprov <= 4 and (recent_opp_c >= 1 or recent_suck <= 1 or n <= 10):
                return 'C'

        if my_last == 'C' and opp_streak == 1 and unprov <= 1 and opp_d <= 2 and recent_opp_c >= 5:
            return 'C'

        return 'D'

    if my_last == 'D':
        if n >= 88 and recent_opp_d == 0 and rng.random() < 0.5:
            return 'D'
        if opp_d == 0 and own_d > 0 and n >= 70 and rng.random() < 0.2:
            return 'D'
        if forg >= 4 and unprov <= 2 and recent_opp_d <= 1 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if n >= 70 and opp_d == 0 and rng.random() < 0.03:
        return 'D'
    if n >= 90 and recent_opp_d <= 1 and rng.random() < 0.08:
        return 'D'

    return 'C'
